def minimum_stick_connection_cost(sticks):
 import heapq
 heap=list(sticks);heapq.heapify(heap);total=0
 while len(heap)>1:
  joined=heapq.heappop(heap)+heapq.heappop(heap);total+=joined;heapq.heappush(heap,joined)
 return total

